import unittest
from solution import rename_fields


class RenameFieldsTests(unittest.TestCase):
    def test_simultaneous_renaming_and_order(self):
        record = {"a": 1, "b": 2, "keep": 3}
        result = rename_fields(record, {"a": "b", "b": "c"})
        self.assertEqual(result, {"b": 1, "c": 2, "keep": 3})
        self.assertEqual(list(result), ["b", "c", "keep"])

    def test_missing_mapping_sources_are_ignored(self):
        record = {"a": 1, "b": 2}
        self.assertEqual(rename_fields(record, {"missing": "a", "a": "x"}), {"x": 1, "b": 2})
        self.assertEqual(rename_fields({}, {"a": "b"}), {})

    def test_detects_final_key_collisions_without_mutation(self):
        record = {"a": [1], "b": [2]}
        mapping = {"a": "b"}
        with self.assertRaises(ValueError):
            rename_fields(record, mapping)
        self.assertEqual(record, {"a": [1], "b": [2]})
        self.assertEqual(mapping, {"a": "b"})
        with self.assertRaises(ValueError):
            rename_fields({"a": 1, "b": 2}, {"a": "x", "b": "x"})

    def test_values_are_deep_copied(self):
        shared = {"nested": [1]}
        record = {"a": shared, "b": shared}
        result = rename_fields(record, {"a": "x", "b": "y"})
        result["x"]["nested"].append(2)
        self.assertEqual(record, {"a": {"nested": [1]}, "b": {"nested": [1]}})
        self.assertEqual(result["y"], {"nested": [1]})
        self.assertIsNot(result["x"], result["y"])
        self.assertEqual(rename_fields(record, {})["a"], {"nested": [1]})

    def test_rejects_malformed_arguments(self):
        cases = [
            ([], {}),
            ({1: "x"}, {}),
            ({}, []),
            ({}, {1: "x"}),
            ({}, {"x": 1}),
        ]
        for record, mapping in cases:
            with self.subTest(record=record, mapping=mapping):
                with self.assertRaises(ValueError):
                    rename_fields(record, mapping)


if __name__ == "__main__":
    unittest.main()

